/**
 * Returns an Account Config object with all the sanitized user-inputted
 * data for a manual config email guess attempt.
 *
 * @returns {AccountConfig}
 */
getIncomingUserConfig() {
  let config = this.#currentConfig.copy();
  config.source = AccountConfig.kSourceUser;

  // Update the type based on the current selection.
  config.incoming.type = InputSanitizer.translate(
    this.#incomingProtocol.value,
    {
      1: "imap",
      2: "pop3",
      3: "exchange",
      4: "ews",
      5: "graph",
      0: null,
    }
  );

  // An EWS configuration won't have any of the default fields available to
  // edit.
  if (config.isExchangeConfig()) {
    config = this.#getExchangeConfigValues(config);
  } else {
    config = this.#getDefaultConfigValues(config);
  }

  config.incoming.auth = InputSanitizer.integer(
    this.#incomingAuthenticationMethod.value
  );
  config.incoming.username = this.#incomingUsername.value;
  !this.#incomingUsername.value
    ? this.#incomingUsername.setAttribute(
        "aria-describedby",
        "incomingUsernameErrorMessage"
      )
    : this.#incomingUsername.removeAttribute("aria-describedby");
  this.#incomingUsername.setAttribute(
    "aria-invalid",
    !this.#incomingUsername.value
  );

  return config;
}

